using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using Newtonsoft.Json.Linq;
using OfficeX.Core;
namespace OfficeX.ExcelHost {
 // The model receives opaque checkpoint IDs. Keys and checkpoint bytes never cross the UI bridge.
 sealed class OfficeFiles:IDisposable {
  readonly object application;readonly string app;readonly Func<OfficeAutomationPort> binding;
  readonly string folder;readonly Dictionary<string,Checkpoint> checkpoints=new Dictionary<string,Checkpoint>();
  sealed class Checkpoint {public string Id,Label,Name,Extension,Hash,Path,State,Validation;public DateTime At;}
  string failedCheckpointDocument;JObject failedCheckpoint;
  public void ResetCheckpointFailure(){failedCheckpointDocument=null;failedCheckpoint=null;}
  public string Folder=>folder;
  public OfficeFiles(object application,string app,Func<OfficeAutomationPort> binding){this.application=application;this.app=app;this.binding=binding;folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OfficeX","Work",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);}
  OfficeFiles(object application,string app,Func<OfficeAutomationPort> binding,string folder,Dictionary<string,Checkpoint> checkpoints){this.application=application;this.app=app;this.binding=binding;this.folder=folder;this.checkpoints=checkpoints;}
  public OfficeFiles Fork(Func<OfficeAutomationPort> binding)=>new OfficeFiles(application,app,binding,folder,checkpoints);
  static void Release(object o){if(o!=null&&Marshal.IsComObject(o))Marshal.ReleaseComObject(o);}
  static string Hash(byte[] data){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
  public string CheckedPath(string path,params string[] extensions){var p=Path.GetFullPath(path??"");if(!String.Equals(Path.GetDirectoryName(p),folder,StringComparison.OrdinalIgnoreCase)||!File.Exists(p)||extensions.Length>0&&!extensions.Contains(Path.GetExtension(p),StringComparer.OrdinalIgnoreCase))throw new OfficeFault("artifact_unavailable");if((File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0||(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new OfficeFault("artifact_unavailable");return p;}
  string FreshPath(string extension)=>Path.Combine(folder,Guid.NewGuid().ToString("N")+extension);
  string ValidateDocument(object value){object doc=value;var observations=new List<object>();object collection=null;try{
   if(app=="word"){object content=null,tables=null,sections=null,images=null;try{content=OfficeDispatch.Get(doc,"Content");tables=OfficeDispatch.Get(doc,"Tables");sections=OfficeDispatch.Get(doc,"Sections");images=OfficeDispatch.Get(doc,"InlineShapes");observations.Add(new{text=Convert.ToString(OfficeDispatch.Get(content,"Text")),tables=Convert.ToInt32(OfficeDispatch.Get(tables,"Count")),sections=Convert.ToInt32(OfficeDispatch.Get(sections,"Count")),images=Convert.ToInt32(OfficeDispatch.Get(images,"Count"))});}finally{Release(images);Release(sections);Release(tables);Release(content);}}
   else if(app=="powerpoint"){collection=OfficeDispatch.Get(doc,"Slides");for(int i=1;i<=Convert.ToInt32(OfficeDispatch.Get(collection,"Count"));i++){object slide=null,shapes=null;try{slide=OfficeDispatch.Get(collection,"Item",i);shapes=OfficeDispatch.Get(slide,"Shapes");var contents=new List<object>();for(int j=1;j<=Convert.ToInt32(OfficeDispatch.Get(shapes,"Count"));j++){object shape=null,frame=null,text=null;try{shape=OfficeDispatch.Get(shapes,"Item",j);string words="";if(Convert.ToInt32(OfficeDispatch.Get(shape,"HasTextFrame"))!=0){frame=OfficeDispatch.Get(shape,"TextFrame");text=OfficeDispatch.Get(frame,"TextRange");words=Convert.ToString(OfficeDispatch.Get(text,"Text"));}contents.Add(new{type=Convert.ToInt32(OfficeDispatch.Get(shape,"Type")),text=words,left=Convert.ToSingle(OfficeDispatch.Get(shape,"Left")),top=Convert.ToSingle(OfficeDispatch.Get(shape,"Top")),width=Convert.ToSingle(OfficeDispatch.Get(shape,"Width")),height=Convert.ToSingle(OfficeDispatch.Get(shape,"Height"))});}finally{Release(text);Release(frame);Release(shape);}}observations.Add(contents);}finally{Release(shapes);Release(slide);}}}
   else{collection=OfficeDispatch.Get(value,"Worksheets");for(int i=1;i<=Convert.ToInt32(OfficeDispatch.Get(collection,"Count"));i++){object sheet=null,range=null;try{sheet=OfficeDispatch.Get(collection,"Item",i);range=OfficeDispatch.Get(sheet,"UsedRange");double count=Convert.ToDouble(OfficeDispatch.Get(range,"CountLarge"));observations.Add(new{name=Convert.ToString(OfficeDispatch.Get(sheet,"Name")),address=Convert.ToString(OfficeDispatch.Get(range,"Address")),formula=count<=20000?OfficeDispatch.Get(range,"Formula"):null,largeRange=count>20000});}finally{Release(range);Release(sheet);}}}
   return Wire.Hash(observations);
  }finally{Release(collection);}}
  static string WordXml(object doc){object content=null;try{content=OfficeDispatch.Get(doc,"Content");return Convert.ToString(OfficeDispatch.Get(content,"WordOpenXML"));}finally{Release(content);}}
  public string State(){binding().CheckSource();object doc=binding().BoundDocument;if(app=="word")return Hash(Encoding.UTF8.GetBytes(WordXml(doc)));var path=Copy();try{return CopyState(path);}finally{File.Delete(path);}}
  string CopyState(string path){if(app=="word")return Hash(File.ReadAllBytes(path));if(app=="excel"){
    // SaveCopyAs preserves the original format; Excel 97-2003 is OLE, not ZIP.
    // Preserve its bytes for source comparison instead of failing before cell writes.
    byte[] header=new byte[8];using(var file=File.OpenRead(path))file.Read(header,0,header.Length);
    bool ole=header.SequenceEqual(new byte[]{0xD0,0xCF,0x11,0xE0,0xA1,0xB1,0x1A,0xE1});
    if(ole||new[]{".csv",".txt",".xml",".html",".htm"}.Contains(Path.GetExtension(path),StringComparer.OrdinalIgnoreCase))return Hash(File.ReadAllBytes(path));
   }using(var zip=ZipFile.OpenRead(path)){var bytes=new MemoryStream();foreach(var e in zip.Entries.OrderBy(x=>x.FullName,StringComparer.Ordinal)){if(e.FullName=="docProps/core.xml"||e.FullName.StartsWith("docProps/thumbnail"))continue;var name=Encoding.UTF8.GetBytes(e.FullName);bytes.Write(name,0,name.Length);using(var source=e.Open())source.CopyTo(bytes);}return Hash(bytes.ToArray());}}
  string Copy(){binding().CheckSource();object doc=binding().BoundDocument;bool macros=false;try{macros=Convert.ToBoolean(OfficeDispatch.Get(doc,"HasVBProject"));}catch(OfficeFault){}string extension=app=="word"?".xml":app=="powerpoint"?(macros?".pptm":".pptx"):Path.GetExtension(Convert.ToString(OfficeDispatch.Get(doc,"Name")));if(app=="excel"){
    // SaveCopyAs keeps the workbook's native FileFormat; a Name suffix is not
    // proof of that format (renamed files and unsaved templates can differ).
    try{int format=Convert.ToInt32(OfficeDispatch.Get(doc,"FileFormat"));var formats=new Dictionary<int,string>{{51,".xlsx"},{61,".xlsx"},{52,".xlsm"},{50,".xlsb"},{56,".xls"},{-4143,".xls"},{54,".xltx"},{53,".xltm"},{17,".xlt"},{6,".csv"},{62,".csv"},{20,".txt"},{21,".txt"},{22,".txt"},{24,".txt"},{42,".txt"},{46,".xml"},{44,".html"}};if(formats.TryGetValue(format,out var actual))extension=actual;}catch(OfficeFault){}
    if(String.IsNullOrEmpty(extension))extension=macros?".xlsm":".xlsx";
   }var path=FreshPath(extension);
   try{if(app=="word")File.WriteAllText(path,WordXml(doc),new UTF8Encoding(false));else if(app=="powerpoint")OfficeDispatch.Call(doc,"SaveCopyAs",path,macros?25:24);else OfficeDispatch.Call(doc,"SaveCopyAs",path);
   if(!File.Exists(path)||new FileInfo(path).Length==0)throw new OfficeFault("checkpoint_failed");return path;}catch{try{if(File.Exists(path))File.Delete(path);}catch{}throw;}
  }
  public object CheckpointNow(string label){var path=Copy();try{var data=File.ReadAllBytes(path);var c=new Checkpoint{Id=Guid.NewGuid().ToString("N"),Label=(label??"문서 변경 전").Substring(0,Math.Min(200,(label??"문서 변경 전").Length)),Name=binding().DocumentName,Extension=Path.GetExtension(path),Hash=Hash(data),State=CopyState(path),Validation=ValidateDocument(binding().BoundDocument),At=DateTime.UtcNow};c.Path=FreshPath(".checkpoint");File.WriteAllBytes(c.Path,ProtectedData.Protect(data,null,DataProtectionScope.CurrentUser));checkpoints.Add(c.Id,c);return new{id=c.Id,label=c.Label,document=c.Name,createdAt=c.At.ToString("o"),encrypted=true};}finally{File.Delete(path);}}
  // A refused backup is not an attempted document edit. Present this result
  // in the existing approval form; do not pretend a rollback point exists.
  public object PrepareCheckpoint(string label){
   binding().CheckSource();string document=binding().DocumentId;if(failedCheckpointDocument==document&&failedCheckpoint!=null)return failedCheckpoint.DeepClone();
   try{var result=Wire.Object(CheckpointNow(label));result["available"]=true;return result;}
   catch(OfficeFault e)when(e.Member=="SaveCopyAs"){OfficeDiagnostics.Record(e,app,"checkpoint_before_write");failedCheckpointDocument=document;failedCheckpoint=Wire.Object(new{available=false,error="checkpoint_copy_unavailable",failedMember=e.Member,nativeCode=e.NativeCode,documentId=document,mutated=false});return failedCheckpoint.DeepClone();}
  }
  public object RequestCheckpoint(string label){var result=Wire.Object(PrepareCheckpoint(label));if((bool?)result["available"]==false){result.Remove("error");result["warning"]="checkpoint_copy_unavailable";result["status"]="unavailable";result["canContinueEditing"]=true;result["recovery"]="No backup was created. Do not retry checkpoint_document this run. Native cell and Office edits still read, review and verify changes. Their review explicitly asks whether to apply without a rollback copy.";}else result["status"]="verified";return result;}
  public object ListCheckpoints()=>checkpoints.Values.OrderByDescending(x=>x.At).Select(c=>new{id=c.Id,label=c.Label,document=c.Name,createdAt=c.At.ToString("o"),restoresAs="new_document"}).ToArray();
  public object ExportCopy(){var state=State();var path=Copy();return new{status="verified",path,format=Path.GetExtension(path).TrimStart('.'),sourceState=state,document=binding().DocumentName};}
  public object ExportPdf(CancellationToken token){binding().CheckSource();token.ThrowIfCancellationRequested();var path=FreshPath(".pdf");object doc=binding().BoundDocument;if(app=="word")OfficeDispatch.Call(doc,"ExportAsFixedFormat",path,17);else if(app=="powerpoint")OfficeDispatch.Call(doc,"ExportAsFixedFormat",path,2);else OfficeDispatch.Call(doc,"ExportAsFixedFormat",0,path);CheckedPath(path,".pdf");return new{status="verified",path,bytes=new FileInfo(path).Length};}
  public object SelectInput(){using(var d=new OpenFileDialog{Title="가져올 파일",Filter="문서|*.pdf;*.docx;*.docm;*.pptx;*.pptm;*.xlsx;*.xlsm;*.md;*.markdown;*.html;*.htm;*.txt;*.csv",Multiselect=false}){if(d.ShowDialog()!=DialogResult.OK)return new{status="rejected"};var path=FreshPath(Path.GetExtension(d.FileName));File.Copy(d.FileName,path);return new{status="verified",path,name=Path.GetFileName(d.FileName)};}}
  public object ReadForMarkdown(CancellationToken token){var port=binding();return WriteMarkdownSnapshot(MarkdownSnapshot.Read(port,token),port.DocumentId);}
  public async Task<object> ReadForMarkdownAsync(CancellationToken token){var port=binding();var source=await MarkdownSnapshot.ReadAsync(port,token);string documentId=port.DocumentId;return await Task.Run(()=>WriteMarkdownSnapshot(source,documentId),token);}
  object WriteMarkdownSnapshot(JObject source,string documentId){byte[] data=Encoding.UTF8.GetBytes(source.ToString(Newtonsoft.Json.Formatting.None));if(data.Length>64*1024*1024)throw new OfficeFault("markdown_source_limit",invocationStarted:false);string path=FreshPath(".json");File.WriteAllBytes(path,data);return new{status="verified",path,sourceHash=Hash(data),documentId,document=(string)source["name"],mutated=false};}
  public static string MarkdownDestination(string destination){if(String.IsNullOrWhiteSpace(destination)||destination.Length>2000)throw new OfficeFault("markdown_destination_invalid",invocationStarted:false);string expanded=Environment.ExpandEnvironmentVariables(destination);
   if(expanded.StartsWith(@"\\.\")||expanded.StartsWith(@"\\?\"))throw new OfficeFault("markdown_destination_invalid",invocationStarted:false);
   if(System.Text.RegularExpressions.Regex.IsMatch(destination,@"%(?!USERPROFILE%|TEMP%|LOCALAPPDATA%)[A-Za-z_]+%",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new OfficeFault("markdown_destination_invalid",invocationStarted:false);
   bool disk=System.Text.RegularExpressions.Regex.IsMatch(expanded,@"^[A-Za-z]:[\\/]");bool network=System.Text.RegularExpressions.Regex.IsMatch(expanded,@"^\\\\[^\\/:*?""<>|]+\\[^\\/:*?""<>|]+\\");if(!disk&&!network||expanded.Substring(disk?2:0).Contains(':'))throw new OfficeFault("markdown_destination_invalid",invocationStarted:false);
   string path=Path.GetFullPath(expanded);if(!String.Equals(Path.GetExtension(path),".md",StringComparison.OrdinalIgnoreCase)||Path.GetFileNameWithoutExtension(path).Length==0||System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileNameWithoutExtension(path),@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new OfficeFault("markdown_destination_invalid",invocationStarted:false);return path;
  }
  public async Task CheckMarkdownSourceAsync(string expectedHash,string documentId,CancellationToken token){if(expectedHash==null)return;var current=Wire.Object(await ReadForMarkdownAsync(token));if((string)current["sourceHash"]!=expectedHash||(string)current["documentId"]!=documentId)throw new OfficeFault("markdown_source_changed",invocationStarted:false);}
  public string PickMarkdownDestination(string path,string title){CheckedPath(path,".md");using(var dialog=new SaveFileDialog{Title="Markdown 저장",FileName=Path.GetFileName(title??path),Filter="Markdown|*.md",DefaultExt="md",AddExtension=true,OverwritePrompt=true}){return dialog.ShowDialog()==DialogResult.OK?MarkdownDestination(dialog.FileName):null;}}
  public void CheckMarkdownSource(string expectedHash,string documentId,CancellationToken token){if(expectedHash==null)return;var current=Wire.Object(ReadForMarkdown(token));if((string)current["sourceHash"]!=expectedHash||(string)current["documentId"]!=documentId)throw new OfficeFault("markdown_source_changed",invocationStarted:false);}
  public object SaveMarkdown(string artifact,string destination,CancellationToken token,string expectedSourceHash=null,string expectedDocumentId=null){artifact=CheckedPath(artifact,".md");destination=MarkdownDestination(destination);token.ThrowIfCancellationRequested();CheckMarkdownSource(expectedSourceHash,expectedDocumentId,token);string dir=Path.GetDirectoryName(destination);Directory.CreateDirectory(dir);
   string stage=Path.Combine(dir,".nubi-"+Guid.NewGuid().ToString("N")+".tmp");byte[] data=File.ReadAllBytes(artifact);string expected=Hash(data);try{using(var stream=new FileStream(stage,FileMode.CreateNew,FileAccess.Write,FileShare.None)){stream.Write(data,0,data.Length);stream.Flush(true);}token.ThrowIfCancellationRequested();if(Hash(File.ReadAllBytes(stage))!=expected)throw new OfficeFault("markdown_save_unverified",invocationStarted:false);
    if(File.Exists(destination))File.Replace(stage,destination,null);else File.Move(stage,destination);
    bool verified=Hash(File.ReadAllBytes(destination))==expected;return new{kind="save_markdown",status=verified?"verified":"partial",saved=verified,mutated=false,document=Path.GetFileName(destination),destination,sha256=expected,bytes=data.Length};
   }finally{if(File.Exists(stage))File.Delete(stage);}
  }
  public object SaveArtifact(string path,string title,Action verifySource=null){path=CheckedPath(path);using(var d=new SaveFileDialog{Title="파일 저장",FileName=Path.GetFileName(title??path),DefaultExt=Path.GetExtension(path).TrimStart('.'),AddExtension=true,OverwritePrompt=true}){if(d.ShowDialog()!=DialogResult.OK)return new{kind="save_artifact",status="rejected",saved=false};verifySource?.Invoke();File.Copy(path,d.FileName,true);bool match=Hash(File.ReadAllBytes(d.FileName))==Hash(File.ReadAllBytes(path));return new{kind="save_artifact",status=match?"verified":"partial",saved=match,document=Path.GetFileName(d.FileName),destination=d.FileName,sha256=Hash(File.ReadAllBytes(path))};}}
  // Restores the complete checkpoint as a visible copy. The document with later edits remains open.
  public object Restore(string id,CancellationToken token){if(id==null||!checkpoints.TryGetValue(id,out var c))throw new OfficeFault("checkpoint_unavailable");token.ThrowIfCancellationRequested();var data=ProtectedData.Unprotect(File.ReadAllBytes(c.Path),null,DataProtectionScope.CurrentUser);if(Hash(data)!=c.Hash)throw new OfficeFault("checkpoint_corrupt");var path=FreshPath(c.Extension);File.WriteAllBytes(path,data);OpenCopy(path);object restored=OfficeDispatch.Get((object)application,app=="word"?"ActiveDocument":app=="powerpoint"?"ActivePresentation":"ActiveWorkbook");bool matches;try{matches=ValidateDocument(restored)==c.Validation;}finally{Release(restored);}return new{kind="rollback_document",status=matches?"verified":"partial",mutated=true,saved=false,checkpointId=id,document=ActiveName(),restoredAs="new_document",originalRetained=true};}
  string ActiveName(){object doc=null;try{doc=OfficeDispatch.Get((object)application,app=="word"?"ActiveDocument":app=="powerpoint"?"ActivePresentation":"ActiveWorkbook");return Convert.ToString(OfficeDispatch.Get(doc,"Name"));}finally{Release(doc);}}
  public void OpenCopy(string path){path=CheckedPath(path,app=="word"?".docx":app=="powerpoint"?".pptx":".xlsx",app=="word"?".xml":app=="powerpoint"?".pptm":".xlsm",app=="excel"?".xlsb":".docm",app=="excel"?".xls":".rtf",app=="word"?".html":".csv");object collection=null,doc=null;int security=0;bool changed=false;
   try{security=Convert.ToInt32(OfficeDispatch.Get((object)application,"AutomationSecurity"));OfficeDispatch.Set((object)application,"AutomationSecurity",3);changed=true;collection=OfficeDispatch.Get((object)application,app=="word"?"Documents":app=="powerpoint"?"Presentations":"Workbooks");
    if(app=="word")doc=OfficeDispatch.Call(collection,"Open",path,false,false,false,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,true);
    else if(app=="powerpoint")doc=OfficeDispatch.Call(collection,"Open",path,0,-1,-1);
    else doc=OfficeDispatch.Call(collection,"Open",path,0,false,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,Type.Missing,false);
    if(app=="powerpoint"){object windows=null,win=null;try{windows=OfficeDispatch.Get(doc,"Windows");win=OfficeDispatch.Get(windows,"Item",1);OfficeDispatch.Call(win,"Activate");}finally{Release(win);Release(windows);}}else OfficeDispatch.Call(doc,"Activate");
    OfficeDispatch.Set(doc,"Saved",app=="powerpoint"?(object)0:false);
   }finally{if(changed)OfficeDispatch.Set((object)application,"AutomationSecurity",security);Release(doc);Release(collection);}
  }
  public object OpenArtifact(string path,string sourceState,CancellationToken token){binding().CheckSource();if(sourceState!=null&&State()!=sourceState)throw new OfficeFault("source_changed");token.ThrowIfCancellationRequested();OpenCopy(path);return new{kind="open_document",status="verified",mutated=true,saved=false,document=ActiveName()};}
  public object ImportSlides(string path,string mode,int slide,string sourceState,CancellationToken token){if(app!="powerpoint")throw new OfficeFault("powerpoint_required");path=CheckedPath(path,".pptx");binding().CheckSource();if(sourceState!=null&&State()!=sourceState)throw new OfficeFault("source_changed");token.ThrowIfCancellationRequested();object doc=binding().BoundDocument;object slides=null;
   if(mode=="new")return OpenArtifact(path,sourceState,token);
   CheckpointNow("발표자료 변경 전");bool mutated=false;try{slides=OfficeDispatch.Get(doc,"Slides");int old=Convert.ToInt32(OfficeDispatch.Get(slides,"Count"));int position=mode=="regenerate"?slide:mode=="replace"?0:old;if(position<0||position>old||mode=="regenerate"&&slide>=old)throw new OfficeFault("slide_index_invalid");mutated=true;int inserted=Convert.ToInt32(OfficeDispatch.Call(slides,"InsertFromFile",path,position));
    if(mode=="replace")for(int i=old+inserted;i>inserted;i--){object s=OfficeDispatch.Get(slides,"Item",i);try{OfficeDispatch.Call(s,"Delete");}finally{Release(s);}}
    else if(mode=="regenerate"){if(inserted!=1)throw new OfficeFault("slide_count_mismatch");object s=OfficeDispatch.Get(slides,"Item",slide+inserted+1);try{OfficeDispatch.Call(s,"Delete");}finally{Release(s);}}
    int expected=mode=="replace"?inserted:mode=="regenerate"?old:old+inserted;bool match=inserted>0&&Convert.ToInt32(OfficeDispatch.Get(slides,"Count"))==expected;
    return new{kind="import_slides",status=match?"verified":"partial",mutated,saved=false,count=inserted,slides=ReadSlideText(),document=binding().DocumentName};
   }catch{if(mutated)return new{kind="import_slides",status="partial",mutated=true,saved=false,error="slide_import_uncertain"};throw;}finally{Release(slides);}
  }
  public object ReadSlideText(){if(app!="powerpoint")throw new OfficeFault("powerpoint_required");binding().CheckSource();object doc=binding().BoundDocument;object slides=null;var values=new List<object>();try{slides=OfficeDispatch.Get(doc,"Slides");for(int i=1;i<=Convert.ToInt32(OfficeDispatch.Get(slides,"Count"));i++){object s=null,shapes=null;try{s=OfficeDispatch.Get(slides,"Item",i);shapes=OfficeDispatch.Get(s,"Shapes");var texts=new List<string>();for(int j=1;j<=Convert.ToInt32(OfficeDispatch.Get(shapes,"Count"));j++){object sh=null,frame=null,range=null;try{sh=OfficeDispatch.Get(shapes,"Item",j);if(Convert.ToInt32(OfficeDispatch.Get(sh,"HasTextFrame"))!=0){frame=OfficeDispatch.Get(sh,"TextFrame");range=OfficeDispatch.Get(frame,"TextRange");texts.Add(Convert.ToString(OfficeDispatch.Get(range,"Text")));}}finally{Release(range);Release(frame);Release(sh);}}values.Add(new{slide=i,texts});}finally{Release(shapes);Release(s);}}return values;}finally{Release(slides);}}
  public object RenderSlides(int first,int count,int width,CancellationToken token){if(app!="powerpoint")throw new OfficeFault("powerpoint_required");binding().CheckSource();if(first<1||count<1||count>20||width<320||width>2560)throw new OfficeFault("render_range_invalid");object slides=null,setup=null;var files=new List<object>();try{object doc=binding().BoundDocument;slides=OfficeDispatch.Get(doc,"Slides");setup=OfficeDispatch.Get(doc,"PageSetup");int total=Convert.ToInt32(OfficeDispatch.Get(slides,"Count"));if(first>total)throw new OfficeFault("slide_index_invalid");int height=(int)Math.Round(width*Convert.ToDouble(OfficeDispatch.Get(setup,"SlideHeight"))/Convert.ToDouble(OfficeDispatch.Get(setup,"SlideWidth")));for(int i=first;i<=Math.Min(total,first+count-1);i++){token.ThrowIfCancellationRequested();object s=OfficeDispatch.Get(slides,"Item",i);var path=FreshPath(".png");try{OfficeDispatch.Call(s,"Export",path,"PNG",width,height);CheckedPath(path,".png");files.Add(new{slide=i,path,width,height});}finally{Release(s);}}return new{status="verified",total,files};}finally{Release(setup);Release(slides);}}
  public object ImportWordContent(string path,string expectedHash,CancellationToken token){if(app!="word")throw new OfficeFault("word_required");path=CheckedPath(path,".html");binding().CheckSource();token.ThrowIfCancellationRequested();CheckpointNow("본문 가져오기 전");object range=null;try{object doc=binding().BoundDocument;range=OfficeDispatch.Get(doc,"Content");OfficeDispatch.Set(range,"Text","");OfficeDispatch.Call(range,"InsertFile",path);object actual=OfficeDispatch.Get(doc,"Content");try{string text=Convert.ToString(OfficeDispatch.Get(actual,"Text"));return new{kind="import_word_content",status=Hash(Encoding.UTF8.GetBytes(System.Text.RegularExpressions.Regex.Replace(text,@"[\s\u0007]+"," ").Trim()))==expectedHash?"verified":"partial",mutated=true,saved=false,document=binding().DocumentName,textLength=text.Length};}finally{Release(actual);}}catch{return new{kind="import_word_content",status="partial",mutated=true,error="content_import_uncertain"};}finally{Release(range);}}

  public void Dispose(){/* encrypted checkpoints remain for the life of this pane; never delete an open generated document */}
 }
}
